"""Whole range header and array implementation with distinct endpoint contracts."""
ROWS = []


def add(path, title, intro, principle, use, sections, questions):
    ROWS.append(dict(path=path, title=title, intro=intro, principle=principle,
                     use=use, area='범위 연산 · 배열 압축 · 용량 제한 · 끝점 계약',
                     sections=sections, questions=questions))


add('include/linux/range.h', 'Range 헤더 전체: 끝점 포함 길이와 배열 API의 계약 차이',
    '두 u64 끝점 자료형과 길이·포함 helper, 범위 배열 연산의 선언을 제공합니다.',
    'range_len은 end-start+1이고 range_contains는 양 끝의 포함 관계를 비교합니다. 선언된 배열 함수의 경계 의미는 구현과 따로 대조해야 합니다.',
    '이 헤더의 모든 함수를 같은 끝점 규약으로 단정하지 않습니다. kernel/range.c의 추가·차감은 start>=end를 거부하고 절단 경계에 ±1을 적용하지 않습니다.',
    [('전체 구성', 'GPL SPDX, guard, types 포함, range 구조체, inline helper 두 개, 배열 연산 선언 다섯 개와 endif로 끝납니다. 구조체는 u64 start와 end만 가지며 별도 유효성·용량 필드는 없습니다.'),
     ('길이와 범위 폭', 'range_len은 end-start+1로 닫힌 범위 길이를 계산합니다. start=end이면1입니다. end<start를 검사하지 않아 unsigned 산술 결과가 될 수 있고 [0,U64_MAX] 전체의 길이2^64도 u64에 담기지 않아0으로 줄어듭니다. 길이 반환만으로 입력의 유효성을 판정하면 안 됩니다.'),
     ('포함 판정', 'range_contains(r1,r2)는 r1.start<=r2.start와 r1.end>=r2.end를 AND합니다. 두 범위의 유효성이나 객체 소유권을 검사하지 않습니다. 끝점 순서가 유효하고 같은 좌표·경계 규약을 사용하는 호출 문맥에서 의미를 해석합니다.'),
     ('배열 API와 단위 차이', 'add_range/add_range_with_merge는 용량 az와 현재 개수 nr_range를 받고 개수를 반환합니다. subtract_range는 용량만 받고 void입니다. clean_sort_range는 전체 슬롯을 정리해 개수를 반환하고 sort_range는 지정 개수만 정렬합니다. kernel/range.c의 절단은 반열린 [start,end)처럼 동작하므로 range_len의 +1 결과를 그 배열의 바이트 수로 무조건 쓰면 안 됩니다.'),
     ('CS 연결', '구조체 타입과 의미 계약의 차이, 닫힌·반열린 구간, unsigned wrap, 길이·용량·활성 개수의 분리를 학습합니다. 같은 이름의 end라도 사용처 구현을 읽어야 합니다.')],
    [('start=end인 구조체의 range_len은?', '1이다', '0이다', '계산식이 end-start+1이므로 닫힌 한 점 구간에서는1입니다. 배열 add_range가 이를 받아들이는지는 별도 계약입니다.'),
     ('[0,U64_MAX]의 range_len을 u64에 담으면?', '0으로 wrap된다', '2^64가 그대로 담긴다', 'u64는2^64를 표현할 수 없습니다. unsigned 연산의 모듈러 결과와 수학적 길이를 구분해야 합니다.'),
     ('range_contains가 두 입력의 start<=end까지 검증하는가?', '아니다. 두 끝점의 상대적 포함 조건만 비교한다', '그렇다. 잘못된 범위를 먼저 거부한다', '본문에는 각 범위의 유효성을 검사하는 분기가 없습니다.')])

add('kernel/range.c', '범위 배열 전체: 추가·병합·차감·압축 정렬',
    '고정 용량 배열에서 범위를 추가하고 병합하며 일부를 빼고 빈 슬롯을 압축합니다.',
    'end0을 빈 슬롯으로 사용합니다. 추가는 뒤에 쓰고, 차감은 삭제·왼쪽 절단·오른쪽 절단·분할로 나누며 압축 후 시작점 기준 정렬을 할 수 있습니다.',
    '유효한 용량·활성 개수와 끝점 규약을 유지해야 합니다. 슬롯 부족을 원자적인 실패로 처리하는 API가 아니므로 호출자가 충분한 공간과 결과를 확인해야 합니다.',
    [('전체 파일', 'GPL SPDX와 범위 추가·차감 설명, init/minmax/printk/sort/string/range 포함, add_range, add_range_with_merge, subtract_range, 비교 함수, clean_sort_range, sort_range로 구성됩니다. 동적 메모리 할당이나 잠금은 없습니다.'),
     ('단순 추가', 'add_range는 start>=end이면 현재 개수를 그대로 반환합니다. nr_range>=az여도 같은 값을 반환해 슬롯 부족을 알리는 별도 errno가 없습니다. 가능하면 range[nr_range]에 두 끝점을 쓰고 개수를1 늘립니다. 기존 빈 슬롯을 찾아 채우거나 정렬·중복 검사를 하지 않습니다. nr_range가 유효한 비음수라는 호출 전제도 필요합니다.'),
     ('병합의 접촉 조건', 'merge는 입력이 비어 있으면 반환하고 활성 개수 범위에서 end0 슬롯을 건너뜁니다. common_start=max(starts), common_end=min(ends)에서 common_start>common_end일 때만 분리합니다. 따라서 [0,4)와 [4,8)처럼 끝과 시작이 같은 범위도 합칩니다. 실제 겹침 또는 인접한 범위를 더 작은 시작과 큰 끝으로 확장합니다.'),
     ('병합과 배열 이동', '합친 기존 슬롯은 memmove로 뒤의 항목을 한 칸 당겨 제거하고 마지막 슬롯을0으로 만듭니다. 개수를 줄이고 i--로 당겨진 같은 위치를 다시 검사합니다. 앞에서 건너뛴 모든 항목을 처음부터 다시 탐색하는 것은 아닙니다. 기존 배열이 이미 병합된 정규 형태인지 같은 선행 조건을 생각해야 하며 무조건 모든 임의 배열을 완전 정규화하는 함수라고 단정하면 안 됩니다. 마지막에 add_range로 합친 결과를 뒤에 넣습니다.'),
     ('차감의 전체 삭제와 한쪽 절단', 'subtract는 start>=end이면 아무것도 하지 않고 az개 전체 슬롯을 검사합니다. 차감 범위가 기존 범위를 덮으면 start/end를0으로 지웁니다. 왼쪽 일부를 덮으면 기존 start=end로, 오른쪽 일부를 덮으면 기존 end=start로 바꿉니다. 절단에 ±1을 쓰지 않아 [a,b) 반열린 범위 연산처럼 동작합니다. 헤더의 range_len과 경계 계약이 다르다는 점이 핵심입니다.'),
     ('가운데 분할과 용량 부족', '차감 범위가 내부에 있으면 end0인 슬롯을 전체 배열에서 찾습니다. 있으면 오른쪽 조각 [차감end,기존end)을 저장하고 기존 슬롯은 왼쪽 조각 [기존start,차감start)으로 줄입니다. 없으면 pr_err를 출력하지만 기존 end=start 대입은 여전히 합니다. 따라서 오른쪽 조각을 잃을 수 있고 void 반환은 그 손실을 오류 코드로 전달하지 않습니다.'),
     ('배열 순서와 개수', '차감은 활성 개수를 받아 갱신하지 않고0 슬롯을 남기거나 빈 슬롯에 새 조각을 추가합니다. 정렬도 보장하지 않습니다. 예를 들어 [0,10)에서[3,7)을 빼면 충분한 슬롯이 있을 때[0,3),[7,10)이며 범위 길이는3+3입니다. 헤더의 +1 길이를 그대로 합하면 각 조각을1씩 과대 계산합니다.'),
     ('압축 후 정렬', 'clean_sort_range는 앞에서 발견한 end0 슬롯을 뒤의 비어 있지 않은 슬롯으로 채우고 원래 뒤 슬롯을0으로 만듭니다. 이후 첫 빈 위치를 찾아 활성 개수를 정하고 그 접두부만 sort합니다. 같은 키의 기존 순서를 유지하는 압축은 아닙니다. az0이면 정렬 개수0으로 반환하는 경로입니다.'),
     ('정렬 비교와 별도 정렬', 'cmp_range는 start만 비교해 -1/0/1을 반환합니다. end는 비교하지 않습니다. sort_range는 지정 nr_range개를 바로 정렬하며 빈 슬롯을 제거하거나 인접 범위를 합치지 않습니다. 정렬과 정규화, 압축은 서로 다른 작업입니다.'),
     ('CS 연결과 비용', '배열의 활성 길이와 용량, sentinel, memmove의 겹침 허용, 구간 차감의 네 경우, 부분 실패와 결과 손실, 비교 함수의 동등 키를 학습합니다. 병합 시 반복 이동과 분할 시 슬롯 검색 때문에 큰 배열에서 여러 선형 작업이 겹칠 수 있습니다. 이 수업은 원본 전체 대조이며 임의 배열의 모든 연산 조합에 대한 실행 증명은 아닙니다.')],
    [('[0,4)와 [4,8)은 merge에서 합쳐지는가?', '그렇다. 접촉 경계도 허용한다', '아니다. 양의 길이 겹침만 허용한다', '분리 조건은 common_start>common_end입니다. 두 값이 같으면 병합 경로로 갑니다.'),
     ('가운데를 빼는데 빈 슬롯이 없으면 원래 범위가 보존되는가?', '아니다. 왼쪽 조각만 남고 오른쪽 조각을 잃을 수 있다', '그렇다. 오류를 반환하고 변경을 되돌린다', '오류 로그 뒤에도 range[j].end=start를 수행합니다. 함수는 void이고 롤백이 없습니다.'),
     ('sort_range가 빈 슬롯 압축과 인접 병합도 하는가?', '아니다. 지정 개수의 시작점 정렬만 한다', '그렇다. 모든 정리 작업을 자동 수행한다', '본문은 sort 호출 하나입니다. 압축은 clean_sort_range, 병합은 별도 추가 API에 있습니다.'),
     ('add_range의 반환 개수가 그대로면 원인을 구분할 수 있는가?', '그 값만으로는 빈 입력과 슬롯 부족을 구분할 수 없다', '항상 슬롯 부족만 뜻한다', 'start>=end와 nr_range>=az 모두 같은 nr_range를 반환합니다. 호출자가 입력과 용량을 함께 확인해야 합니다.')])
